using System.Net;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Web;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using WriterApp.AI.Abstractions;
using WriterApp.AI.Providers.OpenAI;
using WriterApp.Device.Shared.Storage;
using WriterApp.Device.Shared.Services;
using WriterApp.Shared.Brainstorming;
using WriterApp.UI.Shared;
using Xunit;
using static WriterApp.Tests.BrainstormingKeepHostTests;

namespace WriterApp.Tests;

public sealed class BrainstormingVoiceTests {
    internal sealed class Output:IBrainstormingSpeechOutput {
        public event Action<BrainstormingPlaybackProgress>? Progress;
        public int Calls,Stops;public string Mode="complete";public bool Released;public BrainstormingPlayback? Last;public TaskCompletionSource Started=new(TaskCreationOptions.RunContinuationsAsynchronously);
        public Task<BrainstormingCapability> AvailabilityAsync(string language,CancellationToken ct=default)=>Task.FromResult(new BrainstormingCapability(BrainstormingCapabilityState.Available,"Synthetic output adapter; no audible acceptance"));
        public async Task PlayAsync(BrainstormingPlayback value,CancellationToken ct=default){Calls++;Last=value;Released=false;Progress?.Invoke(new(value.Id,BrainstormingPlaybackState.Playing,"Synthetic start"));Started.TrySetResult();try{if(Mode=="wait")await Task.Delay(Timeout.Infinite,ct);if(Mode=="fail")throw new IOException("Synthetic device failure");}finally{Released=true;}}
        public Task StopAsync(){Stops++;Released=true;return Task.CompletedTask;}
        public void Late(Guid id)=>Progress?.Invoke(new(id,BrainstormingPlaybackState.Playing,"Old private playback"));
    }
    private static BrainstormingScope Scope()=>new(1,Guid.NewGuid(),Guid.NewGuid(),null,BrainstormingIdentitySpace.Local,BrainstormingValidation.Fingerprint("https://voice.invalid/"),BrainstormingValidation.Fingerprint("author"),null);
    private static BrainstormingPlayback Playback(BrainstormingScope scope)=>new(1,Guid.NewGuid(),scope,Guid.NewGuid(),BrainstormingValidation.Fingerprint("Answer"),"en","A concise synthetic answer.",BrainstormingPlaybackKind.Answer);
    [Theory][InlineData("schema")][InlineData("source")][InlineData("hash")][InlineData("null")][InlineData("oversize")]
    public async Task InvalidPlaybackNeverEntersOutput(string mode){var output=new Output();await using var voice=new BrainstormingVoiceCoordinator(output);var value=Playback(Scope());value=mode switch {"schema"=>value with{Version=2},"source"=>value with{SourceId=Guid.Empty},"hash"=>value with{Fingerprint=new string('x',64)},"null"=>value with{Text=null!},_=>value with{Text=new string('x',4001)}};await Assert.ThrowsAsync<InvalidDataException>(()=>voice.PlayAsync(value));Assert.Equal(0,output.Calls);Assert.Null(voice.Active);}
    [Theory][InlineData("Keep this version.",BrainstormingVoiceCommand.Keep)][InlineData("Behåll den här versionen.",BrainstormingVoiceCommand.Keep)][InlineData("Approve these planning fields.",BrainstormingVoiceCommand.Planning)][InlineData("Spara dessa planeringsändringar.",BrainstormingVoiceCommand.Planning)]
    [InlineData("Don't keep this version.",BrainstormingVoiceCommand.ConfirmationRequired)][InlineData("Behåll inte denna version.",BrainstormingVoiceCommand.ConfirmationRequired)][InlineData("Keep this version?",BrainstormingVoiceCommand.ConfirmationRequired)][InlineData("Maybe save it later",BrainstormingVoiceCommand.ConfirmationRequired)][InlineData("Make her more suspicious",BrainstormingVoiceCommand.Conversation)]
    public void OnlyExactFinalApplicationPhrasesCanReachAReview( string text,BrainstormingVoiceCommand expected)=>Assert.Equal(expected,BrainstormingVoiceCommands.Classify(text));
    [Theory][InlineData("Make her suspicious, but keep the dialogue understated.")][InlineData("Explore ways she could save her brother.")][InlineData("Behåll dialogen diskret.")]
    public void NarrativeInstructionsRemainConversation(string text)=>Assert.Equal(BrainstormingVoiceCommand.Conversation,BrainstormingVoiceCommands.Classify(text));
    [Theory][InlineData("Keep")][InlineData("Planning")]
    public async Task ApprovalUsesVisibleFrozenOwnedReviewOnceAndRejectsUncertaintyChangesAndForeignScope(string kind){var scope=Scope();var command=Enum.Parse<BrainstormingVoiceCommand>(kind);await using var voice=new BrainstormingVoiceCoordinator(new Output());int commits=0;var current=true;using var review=voice.Register(command,scope,new string('A',64),()=>current,()=>{commits++;return Task.CompletedTask;});var tickets=voice.CaptureReviews(scope);
        Assert.False(await voice.ApproveAsync(scope,command,BrainstormingRecognitionQuality.Unassessed,tickets));Assert.False(await voice.ApproveAsync(scope,command,BrainstormingRecognitionQuality.NeedsReview,tickets));Assert.False(await voice.ApproveAsync(scope with {DocumentId=Guid.NewGuid()},command,BrainstormingRecognitionQuality.Clear,tickets));current=false;Assert.False(await voice.ApproveAsync(scope,command,BrainstormingRecognitionQuality.Clear,tickets));current=true;
        using var changed=voice.Register(command,scope,new string('B',64),()=>true,()=>{commits++;return Task.CompletedTask;});Assert.False(await voice.ApproveAsync(scope,command,BrainstormingRecognitionQuality.Clear,tickets));tickets=voice.CaptureReviews(scope);Assert.True(await voice.ApproveAsync(scope,command,BrainstormingRecognitionQuality.Clear,tickets));Assert.False(await voice.ApproveAsync(scope,command,BrainstormingRecognitionQuality.Clear,tickets));Assert.Equal(1,commits);}
    [Fact]public async Task AudioFloorStopsPlaybackBeforeCaptureAndNeverAllowsEchoCaptureOverlap(){var scope=Scope();var output=new Output{Mode="wait"};await using var voice=new BrainstormingVoiceCoordinator(output);var playback=voice.PlayAsync(Playback(scope));await output.Started.Task.WaitAsync(TimeSpan.FromSeconds(5));await using(var recording=await voice.AcquireMicrophoneAsync(scope)){Assert.True(output.Released);Assert.True(voice.IsCapturing);Assert.Null(voice.Active);await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>playback);await Assert.ThrowsAsync<InvalidOperationException>(()=>voice.PlayAsync(Playback(scope)));await voice.StopAsync(scope);Assert.True(recording.Token.IsCancellationRequested);}Assert.False(voice.IsCapturing);}
    [Fact]public async Task LatePlaybackAndForeignStopsCannotReplaceOrCancelCurrentScope(){var output=new Output{Mode="wait"};await using var voice=new BrainstormingVoiceCoordinator(output);var old=Playback(Scope());var first=voice.PlayAsync(old);await output.Started.Task;var scope=Scope();var latest=Playback(scope);var second=voice.PlayAsync(latest);await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>first);output.Late(old.Id);Assert.Equal(latest.Id,voice.Active!.Id);Assert.DoesNotContain("Old private",voice.Progress!.Message);await voice.StopAsync(old.Scope);Assert.False(second.IsCompleted);await voice.StopAsync(scope);await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>second);Assert.True(output.Released);}
    [Fact]public async Task OutputFailureLeavesTextAndRequiresExplicitNextStart(){var output=new Output{Mode="fail"};await using var voice=new BrainstormingVoiceCoordinator(output);var value=Playback(Scope());await Assert.ThrowsAsync<IOException>(()=>voice.PlayAsync(value));Assert.Null(voice.Active);Assert.Equal(BrainstormingPlaybackState.Failed,voice.Progress!.State);Assert.Equal("A concise synthetic answer.",value.Text);Assert.Equal(1,output.Calls);}
    private sealed class Handler(string mode):HttpMessageHandler {protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Assert.Contains("logprobs",await request.Content!.ReadAsStringAsync(ct));return new(HttpStatusCode.OK){Content=JsonContent.Create(new {text="Keep this version.",usage=new {type="tokens",input_tokens=100,output_tokens=10},logprobs=mode=="missing"?Array.Empty<object>():new object[]{new {token="Keep",logprob=mode=="clear"?-.1:mode=="poor"?-2:.5}}})};}}
    [Theory][InlineData("clear",BrainstormingRecognitionQuality.Clear)][InlineData("poor",BrainstormingRecognitionQuality.NeedsReview)][InlineData("missing",BrainstormingRecognitionQuality.Unassessed)][InlineData("invalid",BrainstormingRecognitionQuality.Unassessed)]
    public async Task ProviderQualityIsEvidenceBasedAndAbsentConfidenceCannotApprove(string mode,BrainstormingRecognitionQuality expected){using var http=new HttpClient(new Handler(mode));var provider=new OpenAiSpeechProvider(http,new(){Enabled=true,Speech=new(){Enabled=true,Model="gpt-4o-mini-transcribe"}},"synthetic");var result=await provider.ExecuteAsync(new(Guid.NewGuid(),OpenAiSpeechProvider.Action,[AiModality.Audio],null!,new(){{"audio",BrainstormingSpeechTests.Wav()},{"language","en"}},[],[]),default);Assert.Equal(expected,result.ProviderMeta["recognitionQuality"]);}
    private sealed class Components:IComponentActivator {public BrainstormingProposalPreview Preview=default!;public IComponent CreateInstance(Type type){var value=(IComponent)Activator.CreateInstance(type)!;if(value is BrainstormingProposalPreview p)Preview=p;return value;}}
    [Fact]public async Task ExplicitReadAloudIsVersionBoundAndProposalEditStopsIt(){var documents=new LocalDocumentRepository(new FileLocalDocumentStore(Path.Combine(Path.GetTempPath(),"P11-read",Guid.NewGuid().ToString())));var document=await documents.CreateAsync("Synthetic manuscript");var scope=Scope() with {DocumentId=document.DocumentId};var session=BrainstormingKeepTests.LocalSession(document,scope,false);var cache=new BrainstormingCache(1,1,session,"",null,null,null,[],[]);var output=new Output{Mode="wait"};var components=new Components();using var services=new ServiceCollection().AddLogging().AddSingleton<IBrainstormingSpeechOutput>(output).AddSingleton<BrainstormingVoiceCoordinator>().AddSingleton<IComponentActivator>(components).BuildServiceProvider();await using var renderer=new HtmlRenderer(services,services.GetRequiredService<ILoggerFactory>());
        await renderer.Dispatcher.InvokeAsync(async()=>{await renderer.RenderComponentAsync<BrainstormingProposalPreview>(ParameterView.FromDictionary(new Dictionary<string,object?>{{"DocumentId",scope.DocumentId},{"Cache",cache}}));});Assert.Equal(0,output.Calls);var reading=renderer.Dispatcher.InvokeAsync(()=>Call(components.Preview,"ReadDraftAloud"));await output.Started.Task.WaitAsync(TimeSpan.FromSeconds(5));var draft=BrainstormingDrafts.Candidate(cache)!;Assert.Equal(draft.Id,output.Last!.SourceId);Assert.Equal(BrainstormingValidation.CandidateFingerprint(draft),output.Last.Fingerprint);await renderer.Dispatcher.InvokeAsync(()=>components.Preview.OnProposalChanged(draft.EditorHtml??BrainstormingDraftContent.Html(draft.PlainText),draft.PlainText,draft.Id,BrainstormingValidation.CandidateFingerprint(draft)));await reading.WaitAsync(TimeSpan.FromSeconds(5));Assert.True(output.Released);Assert.Null(services.GetRequiredService<BrainstormingVoiceCoordinator>().Active);Assert.Empty((await documents.LoadAsync(document.DocumentId))!.Sections[0].Pages[0].Content.Trim());}
}
